const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);
const { stripeClient } = require('../lib/stripe');
const { db } = require('../db');

async function processRefundStreamEvents() {
  while (true) {
    const streams = await redis.xreadgroup(
      'GROUP', 'refund-workers', 'worker-1',
      'BLOCK', 2000, 'COUNT', 10,
      'STREAMS', 'payments:refunds', '>'
    );

    if (!streams) continue;
    for (const [, messages] of streams) {
      for (const [messageId, fields] of messages) {
        const data = Object.fromEntries(fields.reduce((acc, cur, idx) => {
          if (idx % 2 === 0) acc.push([cur, fields[idx + 1]]);
          return acc;
        }, []));

        const { chargeId, amountCents, targetAccountId, requestedByUserId } = data;
        const auth = await db.query(
          'SELECT id FROM account_members WHERE account_id = $1 AND user_id = $2 AND role IN (\'OWNER\', \'FINANCE_ADMIN\')',
          [targetAccountId, requestedByUserId]
        );
        if (auth.rowCount === 0) {
          console.error(`Unauthorized refund dropped: ${chargeId} by ${requestedByUserId}`);
          await redis.xack('payments:refunds', 'refund-workers', messageId);
          continue;
        }

        await stripeClient.refunds.create({
          charge: chargeId,
          amount: parseInt(amountCents, 10)
        });
        await db.query('UPDATE charges SET refunded = true WHERE stripe_id = $1', [chargeId]);
        await redis.xack('payments:refunds', 'refund-workers', messageId);
      }
    }
  }
}
